-- Quick, slightly mechanical: fast start, hard stop. Speeds are in deciseconds.
hl.curve("ng_mech", { type = "bezier", points = { {0.2, 0.9}, {0.1, 1.0} } })
hl.curve("ng_snap", { type = "bezier", points = { {0.5, 0.0}, {0.1, 1.0} } })
hl.animation({ leaf = "global", enabled = true, speed = 1.8, bezier = "ng_mech" })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 1.8, bezier = "ng_mech", style = "popin 92%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 1.2, bezier = "ng_snap", style = "popin 92%" })
hl.animation({ leaf = "windowsMove", enabled = true, speed = 1.8, bezier = "ng_mech" })
hl.animation({ leaf = "border", enabled = true, speed = 2.2, bezier = "ng_mech" })
hl.animation({ leaf = "fade", enabled = true, speed = 1.5, bezier = "ng_mech" })
hl.animation({ leaf = "layers", enabled = true, speed = 1.5, bezier = "ng_mech", style = "fade" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 2.0, bezier = "ng_mech", style = "slide" })

